  return x + recursiveSum(x - 1);
}

try {
  console.log(recursiveSum(10));
} catch (err) {
  console.log("It stopped itself:");
  console.log(err.name + ": " + err.message);
}

function recursiveSum(x) {
  if (x === 0) {
    return 0;
  }
  return x + recursiveSum(x - 1);
}

console.log(recursiveSum(10));

